"""Rebuild the original hard-pixel HUD numeral/key font. No external font licence needed."""
from pathlib import Path
from PIL import Image
GLYPHS = {'0': ['0110', '1001', '1011', '1101', '1001', '0110'], '1': ['010', '110', '010', '010', '010', '111'], '2': ['0110', '1001', '0010', '0100', '1000', '1111'], '3': ['1110', '0001', '0110', '0001', '0001', '1110'], '4': ['1001', '1001', '1111', '0001', '0001', '0001'], '5': ['1111', '1000', '1110', '0001', '0001', '1110'], '6': ['0110', '1000', '1110', '1001', '1001', '0110'], '7': ['1111', '0001', '0010', '0100', '0100', '0100'], '8': ['0110', '1001', '0110', '1001', '1001', '0110'], '9': ['0110', '1001', '1001', '0111', '0001', '0110'], 'A': ['0110', '1001', '1001', '1111', '1001', '1001'], 'B': ['1110', '1001', '1110', '1001', '1001', '1110'], 'C': ['0111', '1000', '1000', '1000', '1000', '0111'], 'D': ['110', '101', '101', '101', '110'], 'E': ['1111', '1000', '1110', '1000', '1000', '1111'], 'F': ['1111', '1000', '1110', '1000', '1000', '1000'], 'G': ['011', '100', '101', '101', '011'], 'H': ['1001', '1001', '1111', '1001', '1001', '1001'], 'I': ['1', '1', '1', '1', '1', '1'], 'J': ['001', '001', '001', '101', '010'], 'K': ['101', '101', '110', '101', '101'], 'L': ['1000', '1000', '1000', '1000', '1000', '1111'], 'M': ['101', '111', '111', '101', '101'], 'N': ['101', '111', '111', '111', '101'], 'O': ['010', '101', '101', '101', '010'], 'P': ['1110', '1001', '1110', '1000', '1000', '1000'], 'Q': ['0110', '1001', '1001', '1011', '1001', '011'], 'R': ['1110', '1001', '1110', '1010', '1001', '1001'], 'S': ['0111', '1000', '0110', '0001', '0001', '1110'], 'T': ['111', '010', '010', '010', '010', '010'], 'U': ['101', '101', '101', '101', '111'], 'V': ['1001', '1001', '1001', '1001', '0110', '0110'], 'W': ['101', '101', '111', '111', '101'], 'X': ['1001', '1001', '0110', '0110', '1001', '1001'], 'Y': ['101', '101', '010', '010', '010'], 'Z': ['1111', '0001', '0010', '0100', '1000', '1111'], ':': ['000', '010', '000', '010', '000'], '/': ['0001', '0010', '0010', '0100', '0100', '1000'], '-': ['000', '000', '111', '000', '000', '000'], '_': ['000', '000', '000', '000', '111'], '?': ['110', '001', '010', '000', '010'], '.': ['000', '000', '000', '000', '010'], ',': ['000', '000', '000', '010', '100'], "'": ['010', '010', '000', '000', '000'], '(': ['001', '010', '010', '010', '001'], ')': ['100', '010', '010', '010', '100'], '!': ['010', '010', '010', '000', '010'], '>': ['100', '010', '001', '010', '100'], ' ': ['00', '00', '00', '00', '00', '00'], '+': ['000', '010', '111', '010', '000', '000'], '%': ['1001', '0001', '0010', '0100', '1000', '1001'], 'x': ['0000', '1001', '0110', '0110', '1001', '0000']}
def main():
 root=Path(__file__).resolve().parent
 im=Image.new('RGBA',(128,64),(0,0,0,0)); records=[]
 for i,(char,rows) in enumerate(sorted(GLYPHS.items())):
  x=(i%16)*8; y=(i//16)*8; width=max(map(len,rows))
  for dy,row in enumerate(rows):
   for dx,c in enumerate(row):
    if c=='1': im.putpixel((x+dx,y+dy),(244,236,214,255))
  records.append(f'char id={ord(char)} x={x} y={y} width={width} height=6 xoffset=0 yoffset=0 xadvance={width+1} page=0 chnl=15')
 im.save(root/'pixel_keys.png')
 head='info face="Totoy Pixel Keys" size=8 bold=0 italic=0 charset="" unicode=1 stretchH=100 smooth=0 aa=1 padding=0,0,0,0 spacing=1,1\ncommon lineHeight=8 base=6 scaleW=128 scaleH=64 pages=1 packed=0\npage id=0 file="pixel_keys.png"\n'
 (root/'pixel_keys.fnt').write_text(head+f'chars count={len(records)}\n'+'\n'.join(records)+'\n',encoding='utf-8')
if __name__=='__main__':main()
